export const onekick_h: string = "/* Shared logic for the 01_OneKick example.\n *\n * The whole program is one voice and a render function, kept in a header\n * so the .ino and the size-report sketch (test/sketches/p4_e1_onekick.cpp)\n * compile the same code and the reported cost is the real one.\n *\n * This is the smallest useful bellows program, and it is the number the\n * rest of the library is measured against: one kick, one include, no\n * registry, no dispatch table. Measured on Cortex-M7 at -Os with\n * --gc-sections, as the p4_e1_onekick row of tools/size-report.sh:\n *\n *     flash 3776 B    RAM 1100 B\n *\n * The 16 bytes over the s1_kick row's 3760 B are this wrapper class and\n * the non-default Params below; a bare Kick with stock parameters is the\n * 3760 B floor.\n *\n * Note what is not here. There is no engine lookup by name, no base class\n * and no virtual call. Kick is a concrete type, the compiler can see\n * every call into it, and the linker never learns that Snare and Hat\n * exist even though they live in the same header. */\n#pragma once\n\n#include \"bellows/engines/drums.h\"\n\nnamespace onekick {\n\n/* A render object: any callable with the library's block signature works\n * as the Render template argument for the Teensy and Daisy adapters. */\nclass Voice {\n public:\n  void Init(float sample_rate) {\n    /* Params defaults match the ParamSpec defaults in the TypeScript\n     * drums.ts exactly, so this kick sounds like the browser one. */\n    bellows::Kick::Params p;\n    p.decay = 0.55f;      /* a little longer than the 0.4 default */\n    p.drive = 3.0f;       /* and pushed harder into the tanh */\n    kick_.Init(sample_rate, p);\n  }\n\n  void Trigger(float hz, float vel) { kick_.NoteOn(hz, vel); }\n\n  /* Voices ADD into the range, so the caller owns clearing the block.\n   * That is the same contract the TypeScript uses, and it is what lets\n   * several voices share one buffer without a mix pass. */\n  void operator()(float* l, float* r, int from, int to) {\n    kick_.Process(l, r, from, to);\n  }\n\n  bool Active() const { return kick_.Active(); }\n\n private:\n  bellows::Kick kick_;\n};\n\n}  // namespace onekick\n";

export const onekick_ino: string = "/*\n * 01_OneKick: the minimum bellows program.\n *\n * One kick drum retriggering twice a second through the Teensy Audio\n * Library. Everything that makes a sound lives in onekick.h; this file is\n * only the board glue, which is the split the library is designed for.\n *\n * MEASURED COST, Cortex-M7, arm-none-eabi-g++ 11.3, -Os, --gc-sections,\n * library only (no Arduino core, no audio library):\n *\n *     flash 3776 B    RAM 1100 B\n *\n * For scale: the same kick reached by string id through a five-engine\n * registry costs 30296 B of flash and 30828 B of RAM. That is the entire\n * argument for how this library is put together.\n *\n * WIRING (Teensy 4.x plus the Audio Shield)\n *   Teensy 4.0/4.1 with a Rev D audio shield, headphones in the jack.\n *   Nothing else is required.\n *\n * PORTING\n *   On a Daisy Seed, replace the AudioStream plumbing with:\n *     #include \"bellows/platform/daisy.h\"\n *     bellows::DaisyAudio<onekick::Voice>::Start(hw, voice);\n *   The Voice class itself does not change. That port is done and built in\n *   examples/daisy_onekick, which includes this folder's onekick.h rather\n *   than copying it, so the claim is checked by the compiler.\n */\n\n#include <Audio.h>\n\n#include \"bellows/platform/teensy.h\"\n#include \"onekick.h\"\n\nstatic onekick::Voice voice;\n\n/* The adapter is the only virtual call in the whole program: the audio\n * library dispatches update() through AudioStream's vtable 344 times a\n * second. Nothing below it is virtual. */\nstatic bellows::BellowsAudioStream<onekick::Voice> node(voice);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  AudioMemory(12);\n  codec.enable();\n  codec.volume(0.6f);\n\n  /* Take the rate from the audio library rather than writing 44100 by\n   * hand: the SAI clock does not land exactly there, and every envelope\n   * coefficient in the voice is derived from this number. */\n  voice.Init(bellows::TeensySampleRate());\n}\n\nvoid loop() {\n  voice.Trigger(50.0f, 0.9f);\n  delay(500);\n}\n";

export const drummachine_h: string = "/* Shared logic for the 02_DrumMachine example.\n *\n * Three drum voices behind a compile-time Bank, each pad driven by its own\n * euclidean pattern. This is the example that shows what replaces the\n * registry: pads are selected by a runtime integer, exactly as they would\n * be by string id in the TypeScript, but Bank resolves that integer\n * through a chain of compile-time-generated compares, so the linker still\n * sees three concrete types and can drop anything they do not reach.\n *\n * Euclidean rhythms are Bjorklund's algorithm, the same one in\n * src/seq/euclid.ts: spread k pulses as evenly as possible over n steps.\n * E(3,8) is the tresillo, E(5,8) the cinquillo, E(2,5) a common clave\n * fragment. The C++ Euclid stores the pattern as a bitmask rather than an\n * array of bools, so a 16 step pattern is two bytes plus a cursor.\n *\n * MEASURED COST, Cortex-M7, -Os, --gc-sections: see the report row for\n * p5_e2_drummachine. The kit is dominated by Snare and Hat, which use\n * BlepOsc and therefore pull in the band-limited step tables; the kick on\n * its own is 3760 B. */\n#pragma once\n\n#include \"bellows/bank.h\"\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/drums.h\"\n#include \"bellows/seq/euclid.h\"\n\nnamespace drummachine {\n\n/* Pad indices into the bank. Declaration order is the dispatch order. */\nenum Pad { kKick = 0, kSnare = 1, kHat = 2, kPadCount = 3 };\n\nclass Machine {\n public:\n  void Init(float sample_rate, unsigned bpm) {\n    rng_.Init(\"drummachine\");\n    sr_ = sample_rate;\n    SetTempo(bpm);\n\n    kit_.head.Init(sample_rate);                 /* Kick  */\n    kit_.tail.head.Init(sample_rate, &rng_);     /* Snare, needs noise */\n    kit_.tail.tail.head.Init(sample_rate);       /* Hat   */\n\n    /* Three patterns that lock together over 16 steps. The kick lands on\n     * a 5-in-16 euclidean spread, the snare answers on the backbeat, and\n     * the hat fills with 11 of 16 rotated by 1 so it never doubles the\n     * kick's downbeat. */\n    pattern_[kKick].Generate(5, 16);\n    pattern_[kSnare].Generate(4, 16, 4);\n    pattern_[kHat].Generate(11, 16, 1);\n\n    /* Tuning per pad, in Hz. Drum engines tune from the noteOn frequency,\n     * so a kit is playable up and down the keyboard. */\n    hz_[kKick] = 50.0f;\n    hz_[kSnare] = 190.0f;\n    hz_[kHat] = 330.0f;\n    vel_[kKick] = 0.95f;\n    vel_[kSnare] = 0.8f;\n    vel_[kHat] = 0.5f;\n  }\n\n  void SetTempo(unsigned bpm) {\n    /* Sixteenth notes: four steps per beat. */\n    float steps_per_sec = (static_cast<float>(bpm) / 60.0f) * 4.0f;\n    samples_per_step_ = static_cast<int>(sr_ / steps_per_sec + 0.5f);\n    if (samples_per_step_ < 1) samples_per_step_ = 1;\n  }\n\n  /* Advance the sequencer one step and fire whichever pads are on. */\n  void Step() {\n    for (int pad = 0; pad < kPadCount; ++pad) {\n      if (!pattern_[pad].Process()) continue;\n      const float f = hz_[pad];\n      const float v = vel_[pad];\n      /* Runtime index into a compile-time bank. No vtable, no table of\n       * function pointers, no string compare. */\n      kit_.With(pad, [f, v](auto& voice) { voice.NoteOn(f, v); });\n    }\n  }\n\n  /* Render one block, splitting it wherever a sequencer step falls so a\n   * hit lands on the exact sample rather than the block boundary. This is\n   * the same block-splitting idea the kernel uses. */\n  void operator()(float* l, float* r, int from, int to) {\n    int i = from;\n    while (i < to) {\n      if (countdown_ <= 0) {\n        Step();\n        countdown_ = samples_per_step_;\n      }\n      int span = to - i;\n      if (span > countdown_) span = countdown_;\n      kit_.ForEach([l, r, i, span](auto& voice) { voice.Process(l, r, i, i + span); });\n      i += span;\n      countdown_ -= span;\n    }\n  }\n\n private:\n  bellows::Rng rng_;\n  bellows::Bank<bellows::Kick, bellows::Snare, bellows::Hat> kit_;\n  bellows::Euclid<16> pattern_[kPadCount];\n  float hz_[kPadCount] = {0.0f, 0.0f, 0.0f};\n  float vel_[kPadCount] = {0.0f, 0.0f, 0.0f};\n  float sr_ = 48000.0f;\n  int samples_per_step_ = 1;\n  int countdown_ = 0;\n};\n\n}  // namespace drummachine\n";

export const drummachine_ino: string = "/*\n * 02_DrumMachine: a three piece kit driven by euclidean patterns.\n *\n * The sequencer runs inside the audio callback, not in loop(), which is\n * the important structural point. loop() on an Arduino is preempted by\n * every interrupt in the system and its timing is worth several\n * milliseconds of jitter; the audio block clock is exact. Machine::Step\n * is called from the render, and the render splits each block at the step\n * boundary so a hit lands on the sample it was scheduled for.\n *\n * All the logic is in drummachine.h so the size-report sketch\n * (test/sketches/p5_e2_drummachine.cpp) measures this same code.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack. Optional: a pot on A0 for tempo.\n */\n\n#include <Audio.h>\n\n#include \"bellows/platform/teensy.h\"\n#include \"drummachine.h\"\n\nstatic drummachine::Machine machine;\n\nstatic bellows::BellowsAudioStream<drummachine::Machine> node(machine);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nstatic const int kTempoPin = A0;\n\nvoid setup() {\n  AudioMemory(12);\n  codec.enable();\n  codec.volume(0.6f);\n  machine.Init(bellows::TeensySampleRate(), 120);\n}\n\nvoid loop() {\n  /* Tempo is the one thing safe to change from loop(): it only affects\n   * how many samples the next step waits, and a torn read costs at worst\n   * one step of the wrong length. Nothing here allocates or blocks. */\n  int raw = analogRead(kTempoPin);          /* 0..1023 */\n  unsigned bpm = 60u + (static_cast<unsigned>(raw) * 120u) / 1023u;  /* 60..180 */\n  machine.SetTempo(bpm);\n  delay(50);\n}\n";

export const polysynth_h: string = "/* Shared logic for the 03_PolySynth example.\n *\n * Eight virtual-analog voices in a VoicePool with an LFO sweeping the\n * filter cutoff. VoicePool is a plain array of Va with the steal order\n * from src/core/voicepool.ts: a free voice first, then the oldest\n * released one, then the oldest held one. Nothing allocates, and note\n * identity is an int the caller chooses, so NoteOff finds its voice\n * without a search structure.\n *\n * The sweep is applied per block rather than per sample, which is the\n * same rate the TypeScript kernel steps a param ramp at. Filter cutoff is\n * a control signal; recomputing it 375 times a second at 128 frames is\n * far above anything audible in the movement and costs one SetParams per\n * voice per block instead of one per sample.\n *\n * Va is the expensive engine in this library (about 28.5 KB) because its\n * oscillators are band-limited and pull in the BLEP residual tables. That\n * is a fixed cost paid once, not per voice: eight voices cost eight times\n * the RAM but the same flash as one. */\n#pragma once\n\n#include \"bellows/config.h\"\n#include \"bellows/core/prng.h\"\n#include \"bellows/dsp/lfo.h\"\n#include \"bellows/engines/va.h\"\n#include \"bellows/voicepool.h\"\n\nnamespace polysynth {\n\ninline constexpr int kPoly = 8;\n\nclass Synth {\n public:\n  void Init(float sample_rate) {\n    rng_.Init(\"polysynth\");\n\n    /* Defaults match va.ts, so this is the browser patch until changed. */\n    bellows::Va::Params p;\n    p.shape = 0.35f;        /* between saw and square */\n    p.detune = 9.0f;        /* cents between the two oscillators */\n    p.sub = 0.25f;\n    p.resonance = 0.55f;    /* enough to hear the sweep sing */\n    p.env_amount = 0.0f;    /* the LFO drives cutoff here, not the envelope */\n    p.attack = 0.01f;\n    p.decay = 0.25f;\n    p.sustain = 0.7f;\n    p.release = 0.35f;\n    base_ = p;\n\n    for (int i = 0; i < kPoly; ++i) pool_.at(i).Init(sample_rate, &rng_, base_);\n\n    /* A slow triangle so the sweep moves in both directions evenly. */\n    sweep_.Init(sample_rate, &rng_);\n    sweep_.SetShape(bellows::LfoShape::kTriangle);\n    sweep_.SetFreq(0.12f);\n  }\n\n  void NoteOn(int note_id, float hz, float vel) { pool_.NoteOn(note_id, hz, vel, frame_); }\n  void NoteOff(int note_id) { pool_.NoteOff(note_id); }\n\n  int ActiveCount() { return pool_.ActiveCount(); }\n\n  void operator()(float* l, float* r, int from, int to) {\n    /* One LFO sample per block drives the whole sweep. */\n    float lfo = sweep_.Process();                 /* -1 .. 1 */\n    float norm = 0.5f * (lfo + 1.0f);             /*  0 .. 1 */\n\n    /* Sweep exponentially, because pitch and filter cutoff are both\n     * perceived in octaves: 200 Hz to 200 * 2^5.5 which is about 9 kHz. */\n    float cutoff = 200.0f * bellows::fm::Exp2(norm * 5.5f);\n\n    bellows::Va::Params p = base_;\n    p.cutoff = bellows::Clamp(cutoff, 40.0f, 16000.0f);\n    for (int i = 0; i < kPoly; ++i) pool_.at(i).SetParams(p);\n\n    pool_.Process(l, r, from, to);\n    frame_ += static_cast<uint32_t>(to - from);\n  }\n\n private:\n  bellows::Rng rng_;\n  bellows::VoicePool<bellows::Va, kPoly> pool_;\n  bellows::Lfo sweep_;\n  bellows::Va::Params base_;\n  uint32_t frame_ = 0;\n};\n\n}  // namespace polysynth\n";

export const polysynth_ino: string = "/*\n * 03_PolySynth: eight voice VA polysynth with a swept filter.\n *\n * Holds a chord and lets the LFO walk the cutoff across it, so the\n * resonance is audible without any playing. Swap the arpeggio in loop()\n * for MIDI input and this becomes example 05.\n *\n * Note ids. VoicePool identifies a sounding note by an integer the caller\n * picks, and NoteOff(id) releases whichever voice is holding it. Using\n * the MIDI note number is the obvious choice and is what example 05 does.\n * Here the chord degrees double as ids.\n *\n * WIRING (Teensy 4.x plus the Rev D audio shield)\n *   Headphones in the jack.\n */\n\n#include <Audio.h>\n\n#include \"bellows/platform/teensy.h\"\n#include \"polysynth.h\"\n\nstatic polysynth::Synth synth;\n\nstatic bellows::BellowsAudioStream<polysynth::Synth> node(synth);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\n/* An A minor 9 spread over two octaves, as MIDI note numbers. */\nstatic const int kChord[] = {45, 52, 57, 60, 64, 67, 71, 76};\nstatic const int kChordSize = sizeof(kChord) / sizeof(kChord[0]);\n\n/* Equal-tempered MIDI to Hz. Example 04 replaces this one line with the\n * tuning layer, which is the point of that example. */\nstatic float MidiToHz(int note) {\n  return 440.0f * powf(2.0f, (static_cast<float>(note) - 69.0f) / 12.0f);\n}\n\nvoid setup() {\n  AudioMemory(16);\n  codec.enable();\n  codec.volume(0.6f);\n  synth.Init(bellows::TeensySampleRate());\n}\n\nvoid loop() {\n  for (int i = 0; i < kChordSize; ++i) {\n    synth.NoteOn(kChord[i], MidiToHz(kChord[i]), 0.7f);\n    delay(180);\n  }\n  delay(2500);\n  for (int i = 0; i < kChordSize; ++i) synth.NoteOff(kChord[i]);\n  delay(1500);\n}\n";

export const audioshield_h: string = "/* Shared patch for the output examples 10 through 14.\n *\n * A plucked chord arriving one note at a time. It exists to give the\n * output examples something with real dynamic range to push through a\n * converter: a kick tells you the wiring works, a decaying string tells\n * you whether the noise floor and the headroom are where you think.\n *\n * WHY THIS FILE IS FULL OF BOARD CONDITIONALS\n *\n * A Karplus-Strong string IS its delay line, and the line has to be long\n * enough for the lowest note it will ever play: at 48 kHz a 20 Hz floor is\n * 2404 samples, which is 9.6 KB of float per voice. Four voices is 38 KB,\n * and a Teensy 3.2 has 64 KB in total with the audio library already in\n * it. Measured, before this file knew what board it was on: `.bss' will\n * not fit in region `RAM', overflowed by 61540 bytes.\n *\n * So the floor is a template parameter, and choosing it is the single most\n * consequential decision in an embedded bellows patch. Raising it from\n * 20 Hz to 100 Hz costs five times less RAM per voice and costs nothing\n * else, as long as no note goes below it. The chord here bottoms out at\n * 110 Hz, so 100 is free on the small boards.\n *\n * This is not a workaround, it is the design: every buffer-owning class in\n * the library takes its size at compile time so the sketch decides, and\n * the library never allocates.\n */\n#pragma once\n\n#include \"bellows/core/prng.h\"\n#include \"bellows/engines/pluck.h\"\n\nnamespace audioshield {\n\n/* Lowest note the strings must be able to play, and how many of them.\n *\n *   Teensy 4.x     512 KB    the full range, four voices, nothing to think about\n *   Teensy 3.5/3.6 256 KB    the same, with room to spare\n *   Teensy 3.2      64 KB    a 100 Hz floor and two voices fits with room\n *   Teensy LC        8 KB    does not fit at all, see examples/README.md\n */\n#if !defined(AUDIOSHIELD_MIN_HZ)\n#if defined(__IMXRT1062__) || defined(__MK64FX512__) || defined(__MK66FX1M0__)\n#define AUDIOSHIELD_MIN_HZ 20\n#define AUDIOSHIELD_VOICES 4\n#else\n#define AUDIOSHIELD_MIN_HZ 100\n#define AUDIOSHIELD_VOICES 2\n#endif\n#endif\n\n/* Overridable so the size-report sketch can pin a configuration. Without\n * that, the freestanding build defines none of the board macros, silently\n * takes the small branch, and the reported cost would be for a patch no\n * Teensy 4.1 sketch ever compiles. */\ninline constexpr int kMinHz = AUDIOSHIELD_MIN_HZ;\ninline constexpr int kVoices = AUDIOSHIELD_VOICES;\n\nusing String = bellows::Pluck<kMinHz>;\n\n/* A minor 7th, which spreads across the octave without any note masking\n * another, so a fault in one voice is audible rather than hidden. The\n * lowest note is 110 Hz, comfortably above the 100 Hz floor above; drop\n * a note below kMinHz and Pluck clamps it, which sounds like the chord\n * silently changing shape. */\ninline constexpr float kChordHz[4] = {110.0f, 130.81f, 164.81f, 196.0f};\n\nclass Patch {\n public:\n  void Init(float sample_rate) {\n    /* One seeded stream per voice, forked from a named root. Two boards\n     * running this sketch produce the same excitation burst in the same\n     * voice on the same note, which is what makes \"does this board sound\n     * different\" a question with an answer. */\n    rng_.Init(\"audioshield\");\n    String::Params p;\n    p.damp = 0.3f;      /* a touch brighter than the 0.35 default */\n    p.decay = 3.0f;     /* and ringing longer, so the tail is audible */\n    p.pick_pos = 0.22f;\n    for (int i = 0; i < kVoices; ++i) {\n      voice_rng_[i].Init(rng_.NextU32());\n      pluck_[i].Init(sample_rate, &voice_rng_[i], p);\n    }\n  }\n\n  /* Round robin, so a fast pattern overlaps its own tails instead of\n   * cutting them. */\n  void Strike(int index, float vel) {\n    const int i = index % kVoices;\n    pluck_[i].NoteOn(kChordHz[index % 4], vel);\n  }\n\n  /* Voices ADD into the range, so the caller owns clearing the block. */\n  void operator()(float* l, float* r, int from, int to) {\n    for (int i = 0; i < kVoices; ++i) pluck_[i].Process(l, r, from, to);\n  }\n\n private:\n  bellows::Rng rng_;\n  bellows::Rng voice_rng_[kVoices];\n  String pluck_[kVoices];\n};\n\n}  // namespace audioshield\n";

export const audioshield_ino: string = "/*\n * 10_AudioShield: bellows through the Teensy Audio Shield (SGTL5000).\n *\n * The reference output path. If you own one shield and one Teensy this is\n * the sketch to start from, because the codec removes every variable the\n * other output examples have to argue about: it is a real 16 bit stereo\n * DAC with a headphone amplifier and a line output, so what you hear is\n * the library rather than the driver.\n *\n * BOARDS\n *   Builds for Teensy 3.2, 3.5, 3.6, 4.0, 4.1 and MicroMod. The shield\n *   comes in two revisions and they are not pin compatible with every\n *   board: Rev D is the 3.x shield, Rev C/D differ for Teensy 4.x. Buy the\n *   revision sold for your board and stack it; no wiring beyond that.\n *\n * WIRING\n *   Stack the shield. Headphones in the jack, or line out to a mixer.\n *   Nothing else. The shield takes I2S on the pins it takes and the audio\n *   library configures them; you do not choose them.\n *\n * WHAT IS VERIFIED\n *   That this builds and links as firmware for the boards listed above.\n *   NOTHING HERE HAS BEEN FLASHED TO A BOARD AND LISTENED TO. See\n *   examples/README.md, which says the same thing once rather than in\n *   every file, and docs/HANDOFF.md, which has said it since the port\n *   started. Assume the first bring-up finds something.\n *\n * THE ONE KNOB THAT MATTERS\n *   codec.volume() drives the headphone amplifier, not the DAC. Leave it\n *   near 0.5 and change the level in the patch instead: turning the\n *   headphone amp up to compensate for a quiet render amplifies the\n *   codec's noise floor along with the music.\n */\n\n#include <Audio.h>\n\n#include \"bellows/platform/teensy.h\"\n#include \"audioshield.h\"\n\nstatic audioshield::Patch patch;\nstatic bellows::BellowsAudioStream<audioshield::Patch> node(patch);\nstatic AudioOutputI2S out;\nstatic AudioControlSGTL5000 codec;\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  /* 12 blocks is enough for a source and a stereo output with headroom.\n   * If update() ever finds the pool dry it returns silence rather than\n   * glitching, so a dropout that sounds like a gap rather than a click is\n   * this number being too small. */\n  AudioMemory(12);\n\n  codec.enable();\n  codec.volume(0.5f);\n\n  /* Take the rate from the audio library rather than writing 44100: the\n   * SAI clock does not land exactly there, and every envelope coefficient\n   * in the patch is derived from this number. */\n  patch.Init(bellows::TeensySampleRate());\n}\n\nvoid loop() {\n  static int n = 0;\n  patch.Strike(n++, 0.8f);\n  delay(400);\n}\n";

export const piezo_h: string = "/* Voicing a bellows patch for a piezo disc.\n *\n * A piezo disc is not a small speaker. It is a capacitor, around 10 to 20\n * nF for a 27 mm brass disc, glued to a metal plate with a sharp mechanical\n * resonance, and it moves almost no air anywhere else. Feeding it the same\n * signal you would send an 8 ohm cone wastes nearly all of the available\n * voltage swing on frequencies it cannot reproduce.\n *\n * There are four things that help, in order of how much:\n *\n * 1. DRIVE IT DIFFERENTIALLY. A logic pin swings 3.3 V. Two pins in\n *    antiphase across the disc swing 6.6 V, which is 6 dB, which is more\n *    than everything below put together. That part is in the .ino, because\n *    it is wiring rather than DSP: this header renders the signal and its\n *    inverse into the two channels.\n *\n * 2. THROW AWAY THE BASS. Not attenuate: remove. The disc's impedance is\n *    1 / (2*pi*f*C), so at 100 Hz a 15 nF disc is about a megaohm and\n *    essentially nothing flows. Every volt spent down there is a volt not\n *    available at 4 kHz, and since the limiter below works on peaks, bass\n *    the disc cannot reproduce still steals headroom from the part it can.\n *    Two poles of highpass, high.\n *\n * 3. BOOST WHERE IT RINGS. The disc has a strong resonance, usually\n *    somewhere between 2 and 6 kHz, and it is much louder there than\n *    anywhere else. Find yours (the .ino has a sweep mode) and put the\n *    bell on it.\n *\n * 4. LIMIT HARD. There is no headroom to protect: the swing is fixed by\n *    the supply and anything above it clips at the pin regardless. So the\n *    useful move is to raise the average level until it is just under the\n *    ceiling all the time, which is what a limiter with a low ceiling and\n *    a fast release does.\n *\n * What this cannot fix: a piezo has no bass, and no amount of processing\n * invents any. A bass line played through one is heard through its\n * harmonics, so patches for a piezo should be written an octave or two up\n * from where they would sit on a speaker.\n */\n#pragma once\n\n#include \"bellows/dsp/filters.h\"\n#include \"bellows/fx/dynamics.h\"\n#include \"bellows/fx/eq.h\"\n\nnamespace piezo {\n\n/* Defaults for a common 27 mm brass disc. Measure yours: the .ino's sweep\n * mode steps a tone across the band so you can hear which is loudest, and\n * that frequency is what belongs in resonance_hz. Mounting changes it, and\n * a disc glued to a box will be lower than a disc held in the air. */\nstruct Voicing {\n  /* Everything below here is thrown away. 1200 is conservative for a bare\n   * disc; a mounted one can usually go lower. */\n  float highpass_hz = 1200.0f;\n  /* The disc's mechanical resonance, and how hard to lean on it. */\n  float resonance_hz = 4000.0f;\n  float resonance_db = 8.0f;\n  float resonance_q = 1.2f;\n  /* Just under full scale. Not 0 dB: the pin clips hard and squarely, and\n   * the last fraction of a dB is not worth the sound of that. */\n  float ceiling_db = -0.5f;\n  float release = 0.02f;\n};\n\n/* Wraps any bellows render and voices its output for a disc. Render is a\n * template parameter for the same reason it is one in the platform\n * adapters: the call inlines and the linker still sees exactly which\n * engines the sketch reaches. */\ntemplate <class Render>\nclass Voiced {\n public:\n  explicit Voiced(Render& render) : render_(&render) {}\n\n  void Init(float sample_rate, const Voicing& v = Voicing()) {\n    v_ = v;\n    /* Two cascaded one-pole-pair highpasses rather than one, because a\n     * single 12 dB slope still leaves plenty of 400 Hz energy in the\n     * limiter's sidechain, and the limiter cannot tell that the disc will\n     * never reproduce it. 24 dB/octave costs four biquads and buys back\n     * real loudness. */\n    for (int i = 0; i < 2; ++i) {\n      for (int c = 0; c < 2; ++c) {\n        hp_[i][c].Init(sample_rate);\n        hp_[i][c].SetMode(bellows::SvfMode::kHp);\n        hp_[i][c].Set(v_.highpass_hz, 0.707f);\n      }\n    }\n    bell_.Init(sample_rate, bellows::SvfMode::kBell, v_.resonance_hz, v_.resonance_q);\n    bell_.Set(v_.resonance_hz, v_.resonance_db, v_.resonance_q, true);\n\n    bellows::Limiter<>::Params lp;\n    lp.ceiling_db = v_.ceiling_db;\n    lp.release = v_.release;\n    limiter_.Init(sample_rate, lp);\n  }\n\n  /* The bellows render signature, so this drops straight into\n   * BellowsAudioStream in place of the patch it wraps. */\n  void operator()(float* l, float* r, int from, int to) {\n    (*render_)(l, r, from, to);\n\n    for (int n = from; n < to; ++n) {\n      float x = 0.5f * (l[n] + r[n]);  /* one disc, so one signal */\n      for (int i = 0; i < 2; ++i) x = hp_[i][0].Process(x);\n      if (!bell_.Bypassed()) x = bell_.Process(0, x);\n      l[n] = x;\n      r[n] = x;\n    }\n\n    limiter_.Process(l, r, from, to);\n\n    /* The differential half of the trick. Left goes to one pin, right to\n     * the other, and the disc sits between them, so it sees twice the\n     * swing either pin can produce on its own. Wire it single-ended and\n     * you get the same sound 6 dB quieter, which still works. */\n    for (int n = from; n < to; ++n) r[n] = -l[n];\n  }\n\n private:\n  Render* render_;\n  Voicing v_;\n  bellows::Svf hp_[2][2];\n  bellows::EqBand bell_;\n  bellows::Limiter<> limiter_;\n};\n\n}  // namespace piezo\n";

export const piezo_ino: string = "/*\n * 15_Piezo: getting the most out of a piezo disc as a loudspeaker.\n *\n * A piezo disc costs about thirty cents, needs no amplifier, and is the\n * cheapest way to make a Teensy audible. It is also a capacitor with a\n * sharp resonance and no bass whatsoever, so the difference between a\n * patch that sounds like a wasp and one that sounds like an instrument is\n * almost entirely in how you drive it. piezo.h is that difference and has\n * the reasoning; this file is the wiring and the two modes.\n *\n * BOARDS\n *   Builds for Teensy 3.2, 3.5, 3.6, 4.0, 4.1 and MicroMod. Teensy 4.x\n *   uses MQS on pins 10 and 12; the 3.x boards use PWM on pins 6 and 9.\n *   Both are selected below by the board macros, so the sketch is the same\n *   either way.\n *\n * WIRING, AND THE ONE THING THAT MATTERS\n *\n *   Teensy 4.x:   pin 10 ---[ piezo disc ]--- pin 12\n *   Teensy 3.x:   pin  6 ---[ piezo disc ]--- pin  9\n *\n *   Across the two pins, NOT from one pin to ground. The sketch renders\n *   the signal on one channel and its exact inverse on the other, so the\n *   disc sees both pins swinging in opposite directions and gets twice\n *   the voltage: 6.6 V peak to peak instead of 3.3. That is 6 dB, free,\n *   and it is the single largest improvement available here.\n *\n *   To ground instead works and is 6 dB quieter. Nothing breaks.\n *\n *   No series resistor is needed for a disc this size, and no capacitor:\n *   a piezo is already a capacitor and passes no DC. Do not put one in\n *   series \"for safety\"; it makes the bass problem worse.\n *\n * A NOTE ON LOUDNESS\n *   The disc will be loud and thin. That is what the part is. If you want\n *   it louder still, glue it to something: a disc lying loose moves almost\n *   nothing, and the same disc on a biscuit tin lid or a stretched\n *   membrane is dramatically louder and drops its resonance, which you\n *   then want to re-measure with SWEEP mode below.\n *\n * TWO MODES\n *   SWEEP  steps a tone from 800 Hz to 8 kHz, a semitone at a time,\n *          printing each frequency. Listen for the loudest, and put that\n *          number in Voicing::resonance_hz. Takes about twenty seconds.\n *   PLAY   the plucked chord from the other output examples, voiced for\n *          the disc.\n *\n * WHAT IS VERIFIED\n *   That this builds and links for the boards listed above. Nothing here\n *   has been flashed to a board, and the piezo advice is engineering\n *   reasoning about a capacitive transducer rather than a measurement.\n *   See examples/README.md.\n */\n\n#include <Audio.h>\n\n#include \"bellows/platform/teensy.h\"\n#include \"../10_AudioShield/audioshield.h\"\n#include \"bellows/dsp/oscillators.h\"\n#include \"piezo.h\"\n\n/* Set to true to hunt for your disc's resonance, false to play. */\nstatic constexpr bool kSweep = false;\n\n/* One source, not two.\n *\n * The first version of this sketch had a node for the chord and a node for\n * the sweep and connected both to the output. The Teensy Audio Library\n * does not mix on a shared destination input: one input takes one\n * connection, and a second AudioConnection to the same port is not an\n * addition. Mixing needs an AudioMixer4, or, as here, one source that\n * knows which of its two generators is running. That also halves the\n * voicing chain, since there is now one of it rather than two.\n */\nstruct Source {\n  audioshield::Patch chord;\n  bellows::BlepOsc osc;\n  bool sweeping = false;\n\n  void Init(float sr) {\n    chord.Init(sr);\n    osc.Init(sr);\n    osc.SetShape(bellows::BlepShape::kSine);\n  }\n\n  void operator()(float* l, float* r, int from, int to) {\n    if (sweeping) {\n      for (int n = from; n < to; ++n) {\n        const float s = 0.9f * osc.Process();\n        l[n] += s;\n        r[n] += s;\n      }\n    } else {\n      chord(l, r, from, to);\n    }\n  }\n};\n\nstatic Source source;\nstatic piezo::Voiced<Source> voiced(source);\nstatic bellows::BellowsAudioStream<piezo::Voiced<Source>> node(voiced);\n\n#if defined(__IMXRT1062__)\n/* MQS: Medium Quality Sound, pins 10 and 12, no external parts at all.\n * It is a sigma-delta output filtered by the disc itself, which for a\n * transducer that rolls off above its resonance is a better match than it\n * sounds. Teensy 4.x only. */\nstatic AudioOutputMQS out;\n#else\n/* PWM on pins 6 and 9. The audio library's own documentation asks for an\n * RC filter for a line output; driving a piezo you can usually omit it,\n * because the disc's own capacitance plus its rolloff does the filtering\n * and there is nothing downstream to offend. */\nstatic AudioOutputPWM out;\n#endif\n\nstatic AudioConnection patchL(node, 0, out, 0);\nstatic AudioConnection patchR(node, 1, out, 1);\n\nvoid setup() {\n  AudioMemory(12);\n  const float sr = bellows::TeensySampleRate();\n\n  source.Init(sr);\n\n  piezo::Voicing v;\n  /* Measure yours with kSweep and change this one number. Everything else\n   * in Voicing is a reasonable default for a bare 27 mm disc. */\n  v.resonance_hz = 4000.0f;\n  voiced.Init(sr, v);\n\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  if (kSweep) {\n    /* 800 Hz up to 8 kHz, a semitone at a time. */\n    source.sweeping = true;\n    for (int semi = 0; semi <= 40; ++semi) {\n      const float hz = 800.0f * powf(2.0f, semi / 12.0f);\n      source.osc.SetFreq(hz);\n      Serial.println(hz);\n      delay(400);\n    }\n    source.sweeping = false;\n    delay(1500);\n  } else {\n    static int n = 0;\n    source.chord.Strike(n++, 0.9f);\n    delay(400);\n  }\n}\n";
